function moveFile(source,target){try{fs.renameSync(source,target);}catch(error){if(error.code!=='EXDEV')throw error;fs.copyFileSync(source,target);fs.unlinkSync(source);}}
function databaseBackupFile(upload){const file=path.resolve(databaseBackupsPath,String(upload.file_path||''));return file.startsWith(databaseBackupsPath+path.sep)?file:null;}
function listFiles(folder){return fs.readdirSync(folder,{withFileTypes:true}).flatMap(item=>{const full=path.join(folder,item.name);return item.isDirectory()?listFiles(full):[full];});}
function migrateLegacyDatabaseBackups(){const legacyRoot=path.join(packagesPath,'bancos');
 for(const row of db.prepare("SELECT id,file_path FROM terminal_database_upload WHERE file_path LIKE 'bancos/%'").all()){const relativePath=row.file_path.slice('bancos/'.length),source=path.resolve(packagesPath,row.file_path),target=path.resolve(databaseBackupsPath,relativePath);if(!source.startsWith(legacyRoot+path.sep)||!target.startsWith(databaseBackupsPath+path.sep))continue;try{if(fs.existsSync(source)){fs.mkdirSync(path.dirname(target),{recursive:true});moveFile(source,target);}db.prepare('UPDATE terminal_database_upload SET file_path=? WHERE id=?').run(relativePath,row.id);}catch(error){console.error(`Falha ao migrar o backup de banco ${row.id}: ${error.message}`);}}
 if(!fs.existsSync(legacyRoot))return;
 // Arquivos sem registro tambem saem da pasta publica.
 for(const source of listFiles(legacyRoot)){const target=path.join(databaseBackupsPath,'sem-registro',path.relative(legacyRoot,source));try{if(fs.existsSync(target))continue;fs.mkdirSync(path.dirname(target),{recursive:true});moveFile(source,target);}catch(error){console.error(`Falha ao mover ${source}: ${error.message}`);}}
 if(!listFiles(legacyRoot).length)fs.rmSync(legacyRoot,{recursive:true,force:true});else console.error(`Ainda ha arquivos em ${legacyRoot}; remova-os manualmente.`);}
migrateLegacyDatabaseBackups();
