  if(targetType==='all')db.prepare("INSERT INTO release_target(release_id,target_type) VALUES(?,'all')").run(id);else for(const clientId of ids)db.prepare("INSERT INTO release_target(release_id,target_type,client_id) VALUES(?,'client',?)").run(id,clientId);
